  const queueSelect=panel.querySelector<HTMLSelectElement>('.reassign-queue')!, techSelect=panel.querySelector<HTMLSelectElement>('.reassign-technician')!, notice=panel.querySelector<HTMLElement>('.reassign-error')!, button=panel.querySelector<HTMLButtonElement>('button')!
  queueSelect.add(new Option('Choose queue',''));queues.forEach(queue=>queueSelect.add(new Option(`${queue.name} · ${queue.team}`,String(queue.id))));queueSelect.value=String(current?.id||'')
