  refresh();queueSelect.addEventListener('change',refresh);button.addEventListener('click',async()=>{if(!queueSelect.value){notice.textContent='Select the destination queue.';return}button.disabled=true;notice.textContent='';try{await api(`/tickets/${id}/reassign`,{method:'POST',body:JSON.stringify({queue_id:+queueSelect.value,assigned_user_id:techSelect.value?+techSelect.value:null})});await load()}catch(e:any){notice.textContent=e.message}finally{button.disabled=false}});anchor.after(panel)
